import{_ as s,a0 as n,w as i,s as l,ao as d,I as p,x as e,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux有問必答：如何查看Linux上程序或進程用到的庫 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何查看Linux上程序或進程用到的庫 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何查看Linux上程序或進程用到的庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何查看Linux上程序或進程用到的庫 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140807 Linux FAQs with Answers--How to check what libraries are used by a program or process on Linux","title":"Linux有問必答：如何查看Linux上程序或進程用到的庫","tag":"201408","desc":""},"relativePath":"201408/20140807 Linux FAQs with Answers--How to check what libraries are used by a program or process on Linux.md","filePath":"[post].md"}'),u={name:"201408/20140807 Linux FAQs with Answers--How to check what libraries are used by a program or process on Linux.md"};function m(x,t,c,f,L,_){const r=n("Link");return i(),l("div",null,[t[11]||(t[11]=d(`<h1 id="linux有問必答-如何查看linux上程序或進程用到的庫" tabindex="-1">Linux有問必答：如何查看Linux上程序或進程用到的庫 <a class="header-anchor" href="#linux有問必答-如何查看linux上程序或進程用到的庫" aria-label="Permalink to “Linux有問必答：如何查看Linux上程序或進程用到的庫”">​</a></h1><blockquote><p><strong>問題</strong>：我想知道當我調用一個特定的可執行文件在運行時載入了哪些共享庫。是否有方法可以明確Linux上可執行程序或運行進程的共享庫依賴關係？</p></blockquote><h3 id="查看可執行程序的共享庫依賴關係" tabindex="-1">查看可執行程序的共享庫依賴關係 <a class="header-anchor" href="#查看可執行程序的共享庫依賴關係" aria-label="Permalink to “查看可執行程序的共享庫依賴關係”">​</a></h3><p>要找出某個特定可執行依賴的庫，可以使用ldd命令。這個命令調用動態鏈接器去找到程序的庫文件依賴關係。</p><pre><code>$ ldd /path/to/program
</code></pre><p><img src="https://farm4.staticflickr.com/3872/14846153231_195cfff0f0_z.jpg" alt=""></p><p>注意！並不推薦為任何不可信的第三方可執行程序運行ldd，因為某些版本的ldd可能會直接調用可執行程序來明確其庫文件依賴關係，這樣可能不安全。</p><p>取而代之的是用一個更安全的方式來顯示一個未知應用程序二進制文件的庫文件依賴，使用如下命令：</p><pre><code>$ objdump -p /path/to/program | grep NEEDED 
</code></pre><p><img src="https://farm6.staticflickr.com/5552/14849218545_e3b667e742_o.png" alt=""></p><p>###查看運行進程的共享庫依賴關係###</p><p>如果你想要找出被一個運行中的進程載入的共享庫，你可以使用pldd命令，它會顯示出在運行時被載入一個進程裏的所有共享對象。</p><pre><code>$ sudo pldd &lt;PID&gt;
</code></pre><p>注意你需要root權限去執行pldd命令。</p><p><img src="https://farm6.staticflickr.com/5570/14846775694_96a6b96592_z.jpg" alt=""></p><p>或者，也可以選擇一個叫做pmap的命令列工具。它報告一個進程的內存映射，也能顯示出運行進程的庫文件依賴。</p><pre><code>$ sudo pmap &lt;PID&gt;
</code></pre><p><img src="https://farm4.staticflickr.com/3919/14848885042_7e5bee2684_z.jpg" alt=""></p><hr>`,19)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(r,{href:"http://ask.xmodulo.com/check-library-dependency-program-process-linux.html"},{default:a(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/check-library-dependency-program-process-linux.html",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(r,{href:"https://github.com/KayGuoWhu"},{default:a(()=>[...t[2]||(t[2]=[e("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const T=s(u,[["render",m]]);export{b as __pageData,T as default};
